// worker/index.ts is generated by `vinext deploy` and is not committed.
// `vinext dev` and `vinext build` read it through wrangler.jsonc's "main" but
// never create it, so generate it first when a fresh clone lacks it.
import { existsSync } from "node:fs"
import { spawnSync } from "node:child_process"

if (!existsSync("worker/index.ts") && !existsSync("worker/index.js")) {
  const { status } = spawnSync("vinext", ["deploy", "--dry-run"], { stdio: "inherit", shell: true })
  process.exit(status ?? 1)
}
